INSERT INTO bridging.notes (id, topic_id, subtopic_name, summary, key_concepts, formulas, worked_examples, common_mistakes, exam_tips, related_topic_codes, order_index, level_band, recommended_levels, curriculum_stage, strand, estimated_minutes, revision_status, created_at, updated_at) VALUES ('019fa77f-0ed2-78b5-bca6-3887a60c34d2'::uuid, '019f9df7-a2a2-78da-b367-27466579928e'::uuid, 'Circle properties and theorems', 'A short list of circle theorems covers nearly every question. Identify which one the diagram is showing before calculating.', ARRAY['The angle in a semicircle is a right angle', 'A tangent meets a radius at 90 degrees', 'Angles in the same segment are equal']::text[], ARRAY['{"note":"Both must stand on the same arc.","label":"Angle at the centre","expression":"angle at centre = 2 x angle at circumference"}'::jsonb, '{"note":"All four vertices must lie on the circle.","label":"Cyclic quadrilateral","expression":"opposite angles add to 180 degrees"}'::jsonb]::text[], ARRAY['{"steps":["Angle ACB = 90 degrees, angle in a semicircle","Angles in triangle ABC sum to 180","Angle ABC = 180 - 90 - 34"],"answer":"56 degrees","question":"A, B and C lie on a circle with AB a diameter. Angle BAC is 34 degrees. Find angle ABC."}'::jsonb]::text[], ARRAY['{"fix":"The centre angle is the larger one. It is double the circumference angle.","mistake":"Halving the wrong angle in the centre and circumference theorem."}'::jsonb, '{"fix":"Check all four vertices lie on the circumference first.","mistake":"Applying the cyclic quadrilateral rule when a vertex is not on the circle."}'::jsonb]::text[], ARRAY['Look for the diameter first, it usually signals a right angle.', 'Name the theorem you used, the reason often carries its own mark.']::text[], ARRAY['t09']::text[], 1101, NULL, NULL, 'O-Level', NULL, NULL, 'published', NULL::timestamptz, '2026-07-28T06:52:29.778Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.notes (id, topic_id, subtopic_name, summary, key_concepts, formulas, worked_examples, common_mistakes, exam_tips, related_topic_codes, order_index, level_band, recommended_levels, curriculum_stage, strand, estimated_minutes, revision_status, created_at, updated_at) VALUES ('019fa780-0e84-7e60-b2fc-65a592509a11'::uuid, '019f9df7-a2a2-78eb-97ed-a2f26cb15634'::uuid, 'Pythagoras and right-angled trigonometry', 'In a right-angled triangle, use Pythagoras for three sides and SOHCAHTOA when an angle is involved.', ARRAY['Hypotenuse is the longest side, opposite the right angle', 'Label opposite, adjacent and hypotenuse relative to the angle you are using', 'Use inverse sin/cos/tan to find an angle from two sides']::text[], ARRAY['{"note":"c is the hypotenuse.","label":"Pythagoras theorem","expression":"a^2 + b^2 = c^2"}'::jsonb, '{"note":"Choose the ratio that uses the two sides you know.","label":"SOHCAHTOA","expression":"sin = O/H; cos = A/H; tan = O/A"}'::jsonb]::text[], ARRAY['{"steps":["Known opposite and hypotenuse, so use sine","sin theta = 3/5 = 0.6","theta = inverse sin(0.6)"],"answer":"theta = 36.9 degrees (1 d.p.)","question":"In a right-angled triangle, opposite = 3, adjacent = 4, hypotenuse = 5. Find the angle theta opposite the side of length 3."}'::jsonb]::text[], ARRAY['{"fix":"Pythagoras only relates three sides. Use trigonometry when an angle appears.","mistake":"Using Pythagoras when one of the given values is an angle."}'::jsonb, '{"fix":"Set the calculator to degrees before any trigonometry.","mistake":"Leaving the calculator in radian mode."}'::jsonb]::text[], ARRAY['Label O, A and H relative to your chosen angle before picking a ratio.', 'Check the hypotenuse is the longest side in your answer.']::text[], ARRAY['t13']::text[], 1201, NULL, NULL, 'O-Level', NULL, NULL, 'published', NULL::timestamptz, '2026-07-28T06:53:35.236Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.notes (id, topic_id, subtopic_name, summary, key_concepts, formulas, worked_examples, common_mistakes, exam_tips, related_topic_codes, order_index, level_band, recommended_levels, curriculum_stage, strand, estimated_minutes, revision_status, created_at, updated_at) VALUES ('019fa780-0e85-70c4-877c-8f32e666862f'::uuid, '019f9df7-a2a2-78eb-97ed-a2f26cb15634'::uuid, 'Sine rule, cosine rule and bearings', 'For triangles without a right angle, choose the sine rule or cosine rule based on what you are given.', ARRAY['Sine rule needs a matching side and opposite angle pair', 'Cosine rule is for two sides and the included angle, or all three sides', 'Bearings are measured clockwise from north as three digits']::text[], ARRAY['{"note":"Use when you have a side and its opposite angle.","label":"Sine rule","expression":"a / sin A = b / sin B = c / sin C"}'::jsonb, '{"note":"A is the angle between sides b and c.","label":"Cosine rule","expression":"a^2 = b^2 + c^2 - 2bc cos A"}'::jsonb, '{"note":"C is the angle between sides a and b.","label":"Area of a triangle","expression":"area = 1/2 ab sin C"}'::jsonb]::text[], ARRAY['{"steps":["Two sides and the included angle, so use the cosine rule","a^2 = 49 + 81 - 2(7)(9)cos 62","a^2 = 130 - 126 x 0.4695 = 70.85","a = square root of 70.85"],"answer":"a = 8.42 cm to 3 significant figures","question":"In triangle ABC, b = 7 cm, c = 9 cm and angle A = 62 degrees. Find a."}'::jsonb]::text[], ARRAY['{"fix":"That case needs the cosine rule, because no side and opposite angle pair is complete.","mistake":"Using the sine rule when you only know two sides and the angle between them."}'::jsonb, '{"fix":"Bearings use three digits, so write 045 degrees.","mistake":"Writing a bearing as 45 degrees."}'::jsonb]::text[], ARRAY['Check what you are given before choosing a rule, it decides the method.', 'For bearings, draw a north arrow at every point mentioned.']::text[], ARRAY['t15']::text[], 1202, NULL, NULL, 'O-Level', NULL, NULL, 'published', NULL::timestamptz, '2026-07-28T06:53:35.236Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.notes (id, topic_id, subtopic_name, summary, key_concepts, formulas, worked_examples, common_mistakes, exam_tips, related_topic_codes, order_index, level_band, recommended_levels, curriculum_stage, strand, estimated_minutes, revision_status, created_at, updated_at) VALUES ('019fa799-85b9-76bf-98d8-05beca89012f'::uuid, '019f9df7-a2a2-78eb-97ed-a2f26cb15634'::uuid, 'Angles of elevation, depression and 3D problems', 'Elevation and depression turn real situations into right-angled triangles. In three dimensions, work one triangle at a time.', ARRAY['An angle of elevation is measured up from the horizontal and an angle of depression is measured down from it', 'The angle of elevation from A to B equals the angle of depression from B to A, because the horizontals are parallel', 'In a 3D problem, pick out one right-angled triangle at a time and redraw it flat', 'You often need Pythagoras on the base before using trigonometry on a vertical triangle']::text[], ARRAY['{"note":"They are alternate angles between two parallel horizontal lines.","label":"Elevation and depression","expression":"angle of elevation = angle of depression"}'::jsonb, '{"note":"Find this first, then use it as the base of the vertical triangle.","label":"Base diagonal of a cuboid","expression":"d = sqrt(l^2 + w^2)"}'::jsonb]::text[], ARRAY['{"steps":["The angle of depression from the cliff equals the angle of elevation at the boat, so the triangle has a 25 degree angle at the boat","The 40 m cliff is opposite that angle and the distance d is adjacent","tan 25 = 40 / d","d = 40 / tan 25 = 40 / 0.4663"],"answer":"85.8 m to 3 significant figures","question":"From the top of a 40 m cliff the angle of depression of a boat is 25 degrees. Find the distance of the boat from the foot of the cliff."}'::jsonb]::text[], ARRAY['{"fix":"Both elevation and depression are measured from the horizontal.","mistake":"Measuring the angle of depression from the vertical."}'::jsonb, '{"fix":"Transfer it to the bottom of the triangle as an equal angle of elevation, which is usually simpler.","mistake":"Using the depression angle directly as the angle inside the triangle at the top."}'::jsonb, '{"fix":"Redraw each right-angled triangle separately and flat before calculating.","mistake":"Trying to solve a 3D problem on the original solid."}'::jsonb]::text[], ARRAY['Sketch the horizontal dashed line first, then mark the elevation or depression angle from it.', 'In 3D questions, name the triangle you are working in before substituting.']::text[], ARRAY['t13']::text[], 1203, NULL, NULL, 'O-Level', NULL, NULL, 'published', NULL::timestamptz, '2026-07-28T07:21:24.153Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.notes (id, topic_id, subtopic_name, summary, key_concepts, formulas, worked_examples, common_mistakes, exam_tips, related_topic_codes, order_index, level_band, recommended_levels, curriculum_stage, strand, estimated_minutes, revision_status, created_at, updated_at) VALUES ('019fa780-0e85-70f7-afe0-beb56ca779e6'::uuid, '019f9df7-a2a2-78fc-bd9e-a40e9b4f9363'::uuid, 'Area, perimeter and circles', 'Break composite shapes into simple ones, and keep track of which parts of the perimeter are actually included.', ARRAY['Perimeter is a length, area is a squared unit', 'An arc is a fraction of the circumference given by its angle', 'Composite shapes are best split into rectangles, triangles and circle parts']::text[], ARRAY['{"note":"Check whether you are given the radius or the diameter.","label":"Circle","expression":"circumference = 2 pi r, area = pi r^2"}'::jsonb, '{"note":"x is the angle at the centre in degrees.","label":"Arc length and sector area","expression":"arc = (x / 360) x 2 pi r, sector = (x / 360) x pi r^2"}'::jsonb]::text[], ARRAY['{"steps":["Radius = 7 cm","Curved part = half of 2 pi x 7 = 7 pi = 21.99 cm","Add the straight diameter: 21.99 + 14"],"answer":"35.99 cm, about 36.0 cm","question":"Find the perimeter of a semicircle of diameter 14 cm."}'::jsonb]::text[], ARRAY['{"fix":"The perimeter is the curved arc plus the diameter.","mistake":"Forgetting the straight edge when finding a semicircle perimeter."}'::jsonb, '{"fix":"Halve the diameter before substituting into the formula.","mistake":"Using the diameter in place of the radius."}'::jsonb]::text[], ARRAY['Write the units on every answer, cm for perimeter and cm^2 for area.', 'Keep pi in your calculator rather than using 3.14 until the final step.']::text[], ARRAY['t10']::text[], 1301, NULL, NULL, 'O-Level', NULL, NULL, 'published', NULL::timestamptz, '2026-07-28T06:53:35.236Z'::timestamptz) ON CONFLICT (id) DO NOTHING;